record.field:
model_name = "res.partner"
package = env["studio.package"]._suggested()
candidates = []
if package:
    candidates = sorted(package._owned_model_names()) + package.model_ids.mapped("model")
for name in candidates:
    if name in env and env["ir.ui.view"].default_view(name, "form"):
        model_name = name
        break
params = {"model": model_name, "view_type": "form", "opened_from": "menu"}
action = {
    "type": "ir.actions.client",
    "tag": "app_builder_console",
    "name": "Console",
    "target": "fullscreen",
    "params": params,
    "context": params,
}
